17	package org.springframework.samples.petclinic.rest.advice;
18	
19	import java.net.URI;
20	import java.time.Instant;
21	import java.util.List;
22	import java.util.Objects;
23	
24	import jakarta.servlet.http.HttpServletRequest;
25	import org.slf4j.Logger;
26	import org.slf4j.LoggerFactory;
27	import org.springframework.dao.DataIntegrityViolationException;
28	import org.springframework.http.HttpStatus;
29	import org.springframework.http.ProblemDetail;
30	import org.springframework.http.ResponseEntity;
31	import org.springframework.samples.petclinic.rest.dto.ValidationMessageDto;
32	import org.springframework.security.access.AccessDeniedException;
33	import org.springframework.validation.BindingResult;
34	import org.springframework.validation.FieldError;
35	import org.springframework.web.bind.MethodArgumentNotValidException;
36	import org.springframework.web.bind.annotation.ControllerAdvice;
37	import org.springframework.web.bind.annotation.ExceptionHandler;
38	import org.springframework.web.bind.annotation.ResponseBody;
39	
40	/**
41	 * Global Exception handler for REST controllers.
42	 * <p>
43	 * This class handles exceptions thrown by REST controllers and returns appropriate HTTP responses to the client.
44	 *
45	 * @author Vitaliy Fedoriv
46	 * @author Alexander Dudkin
47	 */
48	@ControllerAdvice
49	public class ExceptionControllerAdvice {
50	
51	    private static final Logger logger = LoggerFactory.getLogger(ExceptionControllerAdvice.class);
52	    private static final String ERROR_UNEXPECTED = "An unexpected error occurred while processing your request";
53	    private static final String ERROR_DATA_INTEGRITY = "The requested resource could not be processed due to a data constraint violation";
54	    private static final String ERROR_INVALID_REQUEST = "The request contains invalid or missing parameters";
55	
56	    /**
57	     * Private method for constructing the {@link ProblemDetail} object passing the name and details of the exception
58	     * class.
59	     *
60	     * @param e     Object referring to the thrown exception.
61	     * @param status HTTP response status.
62	     * @param url URL request.
63	     */
64	    private ProblemDetail detailBuild(Exception e, HttpStatus status, StringBuffer url, String detail) {
65	        ProblemDetail problemDetail = ProblemDetail.forStatus(status);
66	        problemDetail.setType(URI.create(url.toString()));
67	        problemDetail.setTitle(e.getClass().getSimpleName());
68	        problemDetail.setDetail(detail);
69	        problemDetail.setProperty("timestamp", Instant.now());
70	        problemDetail.setProperty("schemaValidationErrors", List.<ValidationMessageDto>of());
71	        return problemDetail;
72	    }
73	
74	    /**
75	     * Re-throws {@link AccessDeniedException} so Spring Security's {@code ExceptionTranslationFilter}
76	     * translates it as it normally would - 403 for an authenticated user lacking the required role,
77	     * or the configured entry point for an anonymous one. Without this, {@link #handleGeneralException}
78	     * would catch it and report an authorization failure as a 500.
79	     *
80	     * @param e The {@link AccessDeniedException} to propagate
81	     * @throws AccessDeniedException always
82	     */
83	    @ExceptionHandler(AccessDeniedException.class)
84	    public void handleAccessDeniedException(AccessDeniedException e) throws AccessDeniedException {
85	        throw e;
86	    }
87	
88	    /**
89	     * Handles all general exceptions by returning a 500 Internal Server Error status with error details.
90	     *
91	     * @param e The {@link Exception} to be handled
92	     * @param request {@link HttpServletRequest} object referring to the current request.
93	     * @return A {@link ResponseEntity} containing the error information and a 500 Internal Server Error status
94	     */
95	    @ExceptionHandler(Exception.class)
96	    @ResponseBody
97	    public ResponseEntity<ProblemDetail> handleGeneralException(Exception e, HttpServletRequest request) {
98	        logger.error("Unexpected error at {} {}", request.getMethod(), request.getRequestURI(), e);
99	        HttpStatus status = HttpStatus.INTERNAL_SERVER_ERROR;
100	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_UNEXPECTED);
101	        return ResponseEntity.status(status).body(detail);
102	    }
103	
104	    /**
105	     * Handles {@link DataIntegrityViolationException} which typically indicates database constraint violations. This
106	     * method returns a 404 Not Found status if an entity does not exist.
107	     *
108	     * @param e The {@link DataIntegrityViolationException} to be handled
109	     * @param request {@link HttpServletRequest} object referring to the current request.
110	     * @return A {@link ResponseEntity} containing the error information and a 404 Not Found status
111	     */
112	    @ExceptionHandler(DataIntegrityViolationException.class)
113	    @ResponseBody
114	    public ResponseEntity<ProblemDetail> handleDataIntegrityViolationException(DataIntegrityViolationException e, HttpServletRequest request) {
115	        logger.warn("Data integrity violation at {} {}: {}",
116	            request.getMethod(),
117	            request.getRequestURI(),
118	            e.getMessage());
119	        logger.debug("Data integrity violation stacktrace", e);
120	        HttpStatus status = HttpStatus.NOT_FOUND;
121	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_DATA_INTEGRITY);
122	        return ResponseEntity.status(status).body(detail);
123	    }
124	
125	    /**
126	     * Handles exception thrown by Bean Validation on controller methods parameters
127	     *
128	     * @param e The {@link MethodArgumentNotValidException} to be handled
129	     * @param request {@link HttpServletRequest} object referring to the current request.
130	     * @return A {@link ResponseEntity} containing the error information and a 400 Bad Request status.
131	     */
132	    @ExceptionHandler(MethodArgumentNotValidException.class)
133	    @ResponseBody
134	    public ResponseEntity<ProblemDetail> handleMethodArgumentNotValidException(MethodArgumentNotValidException e, HttpServletRequest request) {
135	        HttpStatus status = HttpStatus.BAD_REQUEST;
136	        BindingResult bindingResult = e.getBindingResult();
137	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_INVALID_REQUEST);
138	        if (bindingResult.hasErrors()) {
139	            logger.debug("Validation error at {} {}: {}",
140	                request.getMethod(),
141	                request.getRequestURI(),
142	                bindingResult.getFieldErrors());
143	            detail.setProperty("schemaValidationErrors", schemaValidationErrors(bindingResult));
144	            detail.setProperty("errors", rejectedFieldNames(bindingResult));
145	        }
146	        return ResponseEntity.status(status).body(detail);
147	    }
148	
149	    /**
150	     * Handles {@link MissingOwnerFieldsException}, thrown when a request to create or update an owner omits or leaves
151	     * blank one or more required fields. Reports the offending field names in the {@code errors} array of a
152	     * {@code 400 Bad Request} response.
153	     *
154	     * @param e The {@link MissingOwnerFieldsException} to be handled
155	     * @param request {@link HttpServletRequest} object referring to the current request.
156	     * @return A {@link ResponseEntity} containing the error information and a 400 Bad Request status.
157	     */
158	    @ExceptionHandler(MissingOwnerFieldsException.class)
159	    @ResponseBody
160	    public ResponseEntity<ProblemDetail> handleMissingOwnerFieldsException(MissingOwnerFieldsException e, HttpServletRequest request) {
161	        logger.debug("Missing or blank required fields at {} {}: {}",
162	            request.getMethod(),
163	            request.getRequestURI(),
164	            e.getFields());
165	        return errorResponse(e, HttpStatus.BAD_REQUEST, request, ERROR_INVALID_REQUEST, e.getFields());
166	    }
167	
168	    /**
169	     * Handles {@link InvalidTelephoneException}, thrown when an owner's telephone number cannot be converted into a
170	     * valid E.164 number (8 to 15 digits after the leading {@code '+'}). Returns a {@code 400 Bad Request} reporting the
171	     * {@code telephone} field.
172	     *
173	     * @param e The {@link InvalidTelephoneException} to be handled
174	     * @param request {@link HttpServletRequest} object referring to the current request.
175	     * @return A {@link ResponseEntity} containing the error information and a 400 Bad Request status.
176	     */
177	    @ExceptionHandler(InvalidTelephoneException.class)
178	    @ResponseBody
179	    public ResponseEntity<ProblemDetail> handleInvalidTelephoneException(InvalidTelephoneException e, HttpServletRequest request) {
180	        logger.debug("Invalid telephone at {} {}: {}",
181	            request.getMethod(),
182	            request.getRequestURI(),
183	            e.getMessage());
184	        return errorResponse(e, HttpStatus.BAD_REQUEST, request, ERROR_INVALID_REQUEST, List.of("telephone"));
185	    }
186	
187	    /**
188	     * Handles {@link InvalidPostcodeException}, thrown when an owner supplies a 4-digit postcode that is out of range
189	     * for its city's region (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099). Returns a {@code 400 Bad Request} reporting
190	     * the {@code postcode} field.
191	     *
192	     * @param e The {@link InvalidPostcodeException} to be handled
193	     * @param request {@link HttpServletRequest} object referring to the current request.
194	     * @return A {@link ResponseEntity} containing the error information and a 400 Bad Request status.
195	     */
196	    @ExceptionHandler(InvalidPostcodeException.class)
197	    @ResponseBody
198	    public ResponseEntity<ProblemDetail> handleInvalidPostcodeException(InvalidPostcodeException e, HttpServletRequest request) {
199	        logger.debug("Invalid postcode at {} {}: {}",
200	            request.getMethod(),
201	            request.getRequestURI(),
202	            e.getMessage());
203	        return errorResponse(e, HttpStatus.BAD_REQUEST, request, ERROR_INVALID_REQUEST, List.of("postcode"));
204	    }
205	
206	    /**
207	     * Handles {@link FutureRegistrationDateException}, thrown when a request to create an owner supplies a
208	     * {@code registrationDate} later than the current server date. Returns a {@code 400 Bad Request} reporting the
209	     * {@code registrationDate} field.
210	     *
211	     * @param e The {@link FutureRegistrationDateException} to be handled
212	     * @param request {@link HttpServletRequest} object referring to the current request.
213	     * @return A {@link ResponseEntity} containing the error information and a 400 Bad Request status.
214	     */
215	    @ExceptionHandler(FutureRegistrationDateException.class)
216	    @ResponseBody
217	    public ResponseEntity<ProblemDetail> handleFutureRegistrationDateException(FutureRegistrationDateException e, HttpServletRequest request) {
218	        logger.debug("Future registration date at {} {}: {}",
219	            request.getMethod(),
220	            request.getRequestURI(),
221	            e.getMessage());
222	        return errorResponse(e, HttpStatus.BAD_REQUEST, request, ERROR_INVALID_REQUEST, List.of("registrationDate"));
223	    }
224	
225	    /**
226	     * Handles {@link DisposableEmailException}, thrown when an owner's email uses a domain on the disposable-domain
227	     * blocklist ({@code mailinator.com}, {@code tempmail.com}, {@code guerrillamail.com}). Returns a
228	     * {@code 400 Bad Request} reporting the {@code email} field.
229	     *
230	     * @param e The {@link DisposableEmailException} to be handled
231	     * @param request {@link HttpServletRequest} object referring to the current request.
232	     * @return A {@link ResponseEntity} containing the error information and a 400 Bad Request status.
233	     */
234	    @ExceptionHandler(DisposableEmailException.class)
235	    @ResponseBody
236	    public ResponseEntity<ProblemDetail> handleDisposableEmailException(DisposableEmailException e, HttpServletRequest request) {
237	        logger.debug("Disposable email domain at {} {}: {}",
238	            request.getMethod(),
239	            request.getRequestURI(),
240	            e.getMessage());
241	        return errorResponse(e, HttpStatus.BAD_REQUEST, request, ERROR_INVALID_REQUEST, List.of("email"));
242	    }
243	
244	    /**
245	     * Handles {@link DuplicateOwnerException}, thrown when a request to create an owner carries a whole derived
246	     * {@code identityKey} (the SHA-256 of the normalized telephone, email and last-name Soundex) already used by
247	     * another owner. This is the single, consolidated duplicate rule. Returns a {@code 409 Conflict} reporting the
248	     * {@code telephone}, {@code email} and {@code lastName} fields the key is composed of.
249	     *
250	     * @param e The {@link DuplicateOwnerException} to be handled
251	     * @param request {@link HttpServletRequest} object referring to the current request.
252	     * @return A {@link ResponseEntity} containing the error information and a 409 Conflict status.
253	     */
254	    @ExceptionHandler(DuplicateOwnerException.class)
255	    @ResponseBody
256	    public ResponseEntity<ProblemDetail> handleDuplicateOwnerException(DuplicateOwnerException e, HttpServletRequest request) {
257	        logger.debug("Duplicate owner identity at {} {}: {}",
258	            request.getMethod(),
259	            request.getRequestURI(),
260	            e.getMessage());
261	        return errorResponse(e, HttpStatus.CONFLICT, request, e.getMessage(),
262	            List.of("telephone", "email", "lastName"));
263	    }
264	
265	    /**
266	     * Handles {@link OwnerCityFullException}, thrown when a request to create an owner names a city that already
267	     * contains 50 or more owners (compared case-insensitively). Returns a {@code 409 Conflict} reporting the
268	     * {@code city} field.
269	     *
270	     * @param e The {@link OwnerCityFullException} to be handled
271	     * @param request {@link HttpServletRequest} object referring to the current request.
272	     * @return A {@link ResponseEntity} containing the error information and a 409 Conflict status.
273	     */
274	    @ExceptionHandler(OwnerCityFullException.class)
275	    @ResponseBody
276	    public ResponseEntity<ProblemDetail> handleOwnerCityFullException(OwnerCityFullException e, HttpServletRequest request) {
277	        logger.debug("Owner city at capacity at {} {}: {}",
278	            request.getMethod(),
279	            request.getRequestURI(),
280	            e.getMessage());
281	        return errorResponse(e, HttpStatus.CONFLICT, request, e.getMessage(), List.of("city"));
282	    }
283	
284	    /**
285	     * Handles {@link DailyOwnerLimitExceededException}, thrown when a request to create an owner arrives once 100 or
286	     * more owners have already been created today (compared by {@code registrationDate}). Returns a
287	     * {@code 429 Too Many Requests}.
288	     *
289	     * @param e The {@link DailyOwnerLimitExceededException} to be handled
290	     * @param request {@link HttpServletRequest} object referring to the current request.
291	     * @return A {@link ResponseEntity} containing the error information and a 429 Too Many Requests status.
292	     */
293	    @ExceptionHandler(DailyOwnerLimitExceededException.class)
294	    @ResponseBody
295	    public ResponseEntity<ProblemDetail> handleDailyOwnerLimitExceededException(DailyOwnerLimitExceededException e, HttpServletRequest request) {
296	        logger.debug("Daily owner creation limit reached at {} {}: {}",
297	            request.getMethod(),
298	            request.getRequestURI(),
299	            e.getMessage());
300	        return errorResponse(e, HttpStatus.TOO_MANY_REQUESTS, request, e.getMessage(), List.of());
301	    }
302	
303	    /**
304	     * Builds the response body shared by the handlers that report a single business-rule violation: a
305	     * {@link ProblemDetail} for the given status carrying {@code detail} as its detail message and the offending field
306	     * names in its {@code errors} property.
307	     *
308	     * @param e the exception being handled, used to title the {@link ProblemDetail}
309	     * @param status the HTTP status to return
310	     * @param request {@link HttpServletRequest} object referring to the current request.
311	     * @param detail the human-readable detail message
312	     * @param errors the names of the fields the violation is reported against
313	     * @return a {@link ResponseEntity} carrying the problem detail and the given status
314	     */
315	    private ResponseEntity<ProblemDetail> errorResponse(Exception e, HttpStatus status, HttpServletRequest request,
316	                                                        String detail, List<String> errors) {
317	        ProblemDetail problemDetail = this.detailBuild(e, status, request.getRequestURL(), detail);
318	        problemDetail.setProperty("errors", errors);
319	        return ResponseEntity.status(status).body(problemDetail);
320	    }
321	
322	    /**
323	     * Collects the distinct field names carried by the given {@link BindingResult}, in binding order, so they can be
324	     * reported in the {@code errors} array of a validation error response.
325	     *
326	     * @param bindingResult the binding result carrying the field errors
327	     * @return the names of the rejected fields, without duplicates
328	     */
329	    private List<String> rejectedFieldNames(BindingResult bindingResult) {
330	        return bindingResult.getFieldErrors().stream()
331	            .map(FieldError::getField)
332	            .distinct()
333	            .toList();
334	    }
335	
336	    /**
337	     * Maps every field error in the given {@link BindingResult} to a {@link ValidationMessageDto} describing the
338	     * rejected field, its value and the reason it was rejected.
339	     *
340	     * @param bindingResult the binding result carrying the field errors
341	     * @return one {@link ValidationMessageDto} per field error, in binding order
342	     */
343	    private List<ValidationMessageDto> schemaValidationErrors(BindingResult bindingResult) {
344	        return bindingResult.getFieldErrors().stream()
345	            .map(this::toValidationMessage)
346	            .toList();
347	    }
348	
349	    /**
350	     * Builds a {@link ValidationMessageDto} for a single {@link FieldError}, carrying the field name, rejected value
351	     * and default message both as a human-readable message and as individual properties.
352	     *
353	     * @param fieldError the rejected field
354	     * @return the validation message describing it
355	     */
356	    private ValidationMessageDto toValidationMessage(FieldError fieldError) {
357	        String rejectedValue = Objects.toString(fieldError.getRejectedValue(), "null");
358	        String defaultMessage = Objects.toString(fieldError.getDefaultMessage(), "Validation failed");
359	        String message = "Field '%s' %s (rejected value: %s)".formatted(
360	            fieldError.getField(),
361	            defaultMessage,
362	            rejectedValue);
363	        return new ValidationMessageDto(message)
364	            .putAdditionalProperty("field", fieldError.getField())
365	            .putAdditionalProperty("rejectedValue", rejectedValue)
366	            .putAdditionalProperty("defaultMessage", defaultMessage);
367	    }
368	
369	}
